package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DirectClientTransportTest {
 @Test public void unknownOperationDoesNotImplyBrokenTransport(){assertFalse(DirectClientTransport.shouldClose(Map.of("state","outcome_unknown","transport_state","usable")));assertTrue(DirectClientTransport.shouldClose(Map.of("state","outcome_unknown","transport_state","broken")));}
 @Test public void legacyFailuresRemainFailClosed(){assertTrue(DirectClientTransport.shouldClose(Map.of("state","transport_failed")));assertTrue(DirectClientTransport.shouldClose(Map.of("state","outcome_unknown")));assertFalse(DirectClientTransport.shouldClose(Map.of("success",true)));}
 @Test public void provenUnsentWorkerRequestCannotBecomeUnknownMutation(){var f=new DirectClientTransport.WorkerFailure(false,Map.of("failure_kind","worker_unavailable_before_request"),null);var r=DirectClientTransport.failure(f,true);assertEquals(false,r.get("outcome_unknown"));assertEquals(false,r.get("action_dispatched"));assertEquals("not_dispatched",r.get("execution_state"));}
 @Test public void sentRequestLostReplyNeverClaimsNoDispatch(){var r=DirectClientTransport.failure(new DirectClientTransport.WorkerFailure(true,Map.of("failure_kind","worker_reply_timeout"),null),true);assertEquals(true,r.get("outcome_unknown"));assertFalse(r.containsKey("action_dispatched"));assertEquals("not_proven",r.get("action_dispatch_state"));assertEquals(false,r.get("retry_safe"));}
 @Test public void observationFailureCannotClaimAnUnknownMutation(){var r=DirectClientTransport.failure(new DirectClientTransport.WorkerFailure(true,Map.of("failure_kind","worker_reply_timeout"),null),false);assertEquals(false,r.get("outcome_unknown"));assertEquals(false,r.get("action_dispatched"));}
 @Test public void genericFailureAfterRequestRemainsConservative(){assertEquals(true,DirectClientTransport.failure(new java.io.IOException("private value"),true).get("outcome_unknown"));assertFalse(AgentResponses.JSON.toJson(DirectClientTransport.failure(new java.io.IOException("private value"),true)).contains("private value"));}
 @Test public void unicodePayloadBoundCheckedBeforeAnyClaim(){assertThrows(IllegalArgumentException.class,()->DirectClientTransport.validatePayload(Map.of("value","я".repeat(70000))));DirectClientTransport.validatePayload(Map.of("value","normal"));}
 @Test public void summaryPreservesSafeFailureEvidence(){var diagnostics=Map.of("failure_kind","wire_timeout","worker_pid",123);var full=Map.<String,Object>of("success",false,"state","transport_failed","transport_state","broken","execution_state","not_dispatched","diagnostics",diagnostics,"reason","TimeoutError");var r=DirectTestClientService.present(full,Map.of("action","close","response_mode","summary"),"op");assertEquals(diagnostics,r.get("diagnostics"));assertEquals("broken",r.get("transport_state"));assertEquals("not_dispatched",r.get("execution_state"));}
 @Test public void exactUtf8PayloadLimitReservesNewlineOnWorkerSide(){int overhead=AgentResponses.JSON.toJson(Map.of("value","")).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;String value="x".repeat(128*1024-overhead);DirectClientTransport.validatePayload(Map.of("value",value));assertThrows(IllegalArgumentException.class,()->DirectClientTransport.validatePayload(Map.of("value",value+"x")));}
 @Test public void oversizedBatchSummaryRetainsProvenStepCounts(){var full=Map.<String,Object>of("success",false,"state","result_too_large","payload_truncated",true,"execution_success",true,"finished_steps",3,"passed_steps",3,"verified_steps",2);var summary=DirectTestClientService.present(full,Map.of("action","batch","response_mode","summary","steps",List.of(Map.of(),Map.of(),Map.of())),"op");assertEquals(3,summary.get("finished_steps"));assertEquals(3,summary.get("passed_steps"));assertEquals(2,summary.get("verified_steps"));assertEquals(true,summary.get("payload_truncated"));assertEquals(true,summary.get("execution_success"));}
 @org.junit.Test public void correlationMetadataMustFitBeforeClaim(){var payload=Map.<String,Object>of("code","x".repeat(128*1024-30));DirectClientTransport.validatePayload(payload);org.junit.Assert.assertThrows(IllegalArgumentException.class,()->DirectClientTransport.wirePayload(payload,"a".repeat(64)));}
}
